begin;
-- Synthetic records only. Provider calls are tested separately with fake transports.
do $$ declare salon uuid;stylist uuid;service uuid;start_at timestamptz;r public.booking_requests;r2 public.booking_requests;j public.notification_jobs;j2 public.notification_jobs;b jsonb;request_key uuid;bad boolean;count_before integer;owner_id uuid;outsider uuid;begin
 insert into public.salons(name) values('Communications/payment fixture') returning id into salon;
 insert into public.locations(id,salon_id,name) values(salon,salon,'Fixture location');
 insert into public.stylists(location_id,name) values(salon,'Fixture stylist') returning id into stylist;
 insert into public.staff(salon_id,stylist_id,name) values(salon,stylist,'Fixture stylist');
 insert into public.booking_policies(salon_id,minimum_notice_minutes) values(salon,0);
 insert into public.communication_settings(salon_id,email_enabled) values(salon,true);
 insert into public.salon_profiles(salon_id,phone,email) values(salon,'5550000000','fixture@example.invalid');
 insert into public.services(salon_id,slug,name,category,price_cents,duration_minutes,price_approved,duration_approved,status) values(salon,'fixture-service','Fixture service','EXTRAS',6001,30,true,true,'published') returning id into service;
 start_at=((current_date+7)+'10:00'::time) at time zone 'America/Chicago';
 insert into public.availability(stylist_id,starts_at,ends_at) values(stylist,start_at-interval '1 hour',start_at+interval '9 hours');
 b=jsonb_build_object('service_id',service,'variant_id',null,'stylist_id',stylist,'starts_at',start_at,'name','Fixture Customer','email','fixture-first@example.invalid','phone','+15550000001','email_reminders_consent',true,'sms_consent',false);
 request_key=gen_random_uuid();r=public.begin_booking(request_key,repeat('a',64),b);
 r2=public.begin_booking(request_key,repeat('a',64),b);
 if r.status<>'confirmed' or r.appointment_id<>r2.appointment_id or r.deposit_cents<>0 or r.paid_cents<>0 then raise exception 'TEST: no-deposit/idempotent booking failed';end if;
 if (select count(*) from public.notification_jobs where appointment_id=r.appointment_id)<>1 or exists(select 1 from public.notification_jobs where appointment_id=r.appointment_id and kind='reminder') then raise exception 'TEST: unapproved reminder or duplicate confirmation';end if;
 if not exists(select 1 from public.appointments where id=r.appointment_id and email_reminders_consent and consent_version='booking-v1') then raise exception 'TEST: consent missing';end if;
 bad=false;begin perform public.begin_booking(request_key,repeat('b',64),b);exception when others then bad=true;end;if not bad then raise exception 'TEST: wrong capability recovered booking';end if;
 update public.communication_settings set reminders_enabled=true where salon_id=salon;
 if (select count(*) from public.notification_jobs where appointment_id=r.appointment_id and kind='reminder' and state='pending')<>2 then raise exception 'TEST: approved 24h/2h reminders missing';end if;
 update public.appointments set starts_at=start_at+interval '1 hour',ends_at=start_at+interval '90 minutes' where id=r.appointment_id;
 if (select count(*) from public.notification_jobs where appointment_id=r.appointment_id and kind='reminder' and state='pending')<>2 then raise exception 'TEST: reschedule reminder replacement failed';end if;
 update public.appointments set status='cancelled' where id=r.appointment_id;
 if exists(select 1 from public.notification_jobs where appointment_id=r.appointment_id and state='pending' and kind<>'cancellation') then raise exception 'TEST: stale messages survived cancellation';end if;
 select * into strict j from public.claim_messages('email');
 if j.kind<>'cancellation' then raise exception 'TEST: cancellation not claimable';end if;
 if exists(select 1 from public.claim_messages('email')) then raise exception 'TEST: concurrent lease claimed twice';end if;
 if public.freeze_message(j.id,j.lease_token,'resend','{"text":"immutable"}') is null then raise exception 'TEST: freeze failed';end if;
 if not public.finish_message(j.id,j.lease_token,'retry',null,'fixture_429') then raise exception 'TEST: retry failed';end if;
 update public.notification_jobs set locked_until=now()-interval '1 minute' where id=j.id;
 select * into strict j2 from public.claim_messages('email');
 if j2.id<>j.id or j2.lease_token=j.lease_token or j2.attempts<>2 then raise exception 'TEST: retry identity/lease failed';end if;
 if public.freeze_message(j2.id,j2.lease_token,'resend','{"text":"changed"}')->>'text'<>'immutable' then raise exception 'TEST: retry changed provider body';end if;
 if public.finish_message(j.id,j.lease_token,'accepted','wrong') then raise exception 'TEST: stale worker acknowledged delivery';end if;
 perform public.finish_message(j2.id,j2.lease_token,'accepted','email_fixture');
 perform public.record_delivery_event('resend','evt_delivery','email_fixture','delivered');
 perform public.record_delivery_event('resend','evt_delivery','email_fixture','delivered');
 if (select count(*) from public.notification_events where job_id=j.id and event_type='delivered')<>1 then raise exception 'TEST: duplicate delivery event';end if;
 if exists(select 1 from public.claim_messages('email')) then raise exception 'TEST: delivered message claimed again';end if;
 -- Deposit activation requires both infrastructure checks and owner policy.
 bad=false;begin update public.booking_policies set payments_enabled=true,deposit_type='percent',deposit_value=25,cancellation_notice_hours=24,cancellation_text='Fixture cancellation terms',refund_policy='Fixture refund terms' where salon_id=salon;exception when others then bad=true;end;if not bad then raise exception 'TEST: payments activated without readiness';end if;
 insert into public.payment_readiness(salon_id,credential_fingerprint,account_id,endpoint_id,livemode,verified_at,webhook_seen_at) values(salon,'fixture-fingerprint','acct_fixture','we_fixture',false,now(),now());
 update public.booking_policies set payments_enabled=true,deposit_type='percent',deposit_value=25,cancellation_notice_hours=24,cancellation_text='Fixture cancellation terms',refund_policy='Fixture refund terms' where salon_id=salon;
 b=b||jsonb_build_object('email','fixture-paid@example.invalid','email_reminders_consent',false);
 bad=false;begin perform public.begin_booking(gen_random_uuid(),repeat('a',64),b,'wrong',false);exception when others then bad=true;end;if not bad then raise exception 'TEST: wrong credentials accepted';end if;
 r=public.begin_booking(gen_random_uuid(),repeat('a',64),b,'fixture-fingerprint',false);
 if r.status<>'pending' or r.appointment_id is not null or r.deposit_cents<>1501 then raise exception 'TEST: checkout prematurely confirmed or amount incorrect';end if;
 if exists(select 1 from public.available_slots(service,(start_at at time zone 'America/Chicago')::date) where starts_at=start_at) then raise exception 'TEST: deposit hold did not exclude slot';end if;
 perform public.attach_checkout(r.id,'cs_fixture_paid','https://checkout.stripe.com/fixture');
 if (select status from public.booking_requests where public.booking_requests.id=r.id)<>'pending' then raise exception 'TEST: opened Checkout confirmed appointment';end if;
 bad=false;begin perform public.apply_payment_event('evt_wrong','paid',r.id,'cs_fixture_paid','pi_fixture_paid',999,'usd',false);exception when others then bad=true;end;if not bad then raise exception 'TEST: wrong paid amount accepted';end if;
 if public.apply_payment_event('evt_paid','paid',r.id,'cs_fixture_paid','pi_fixture_paid',1501,'usd',false)<>'confirmed' then raise exception 'TEST: paid booking not confirmed';end if;
 perform public.apply_payment_event('evt_paid','paid',r.id,'cs_fixture_paid','pi_fixture_paid',1501,'usd',false);
 perform public.apply_payment_event('evt_paid_again','paid',r.id,'cs_fixture_paid','pi_fixture_paid',1501,'usd',false);
 select * into r from public.booking_requests where public.booking_requests.id=r.id;
 if r.paid_cents<>1501 or r.appointment_id is null or (select count(*) from public.notification_jobs where appointment_id=r.appointment_id and kind='confirmation')<>1 then raise exception 'TEST: payment duplicate/confirmation handling';end if;
 perform public.apply_refund_event('evt_refund','pi_fixture_paid',500);perform public.apply_refund_event('evt_refund','pi_fixture_paid',500);
 if (select refunded_cents from public.booking_requests where public.booking_requests.id=r.id)<>500 then raise exception 'TEST: duplicate refund changed amount';end if;
 -- Failed and abandoned checkout attempts release slots, without confirmations.
 b=b||jsonb_build_object('starts_at',start_at+interval '2 hours','email','fixture-failed@example.invalid');
 r=public.begin_booking(gen_random_uuid(),repeat('a',64),b,'fixture-fingerprint',false);
 perform public.apply_payment_event('evt_failed','failed',r.id,'cs_fixture_failed',null,1501,'usd',false);
 if not exists(select 1 from public.available_slots(service,(start_at at time zone 'America/Chicago')::date) where starts_at=start_at+interval '2 hours') then raise exception 'TEST: failed checkout hold not released';end if;
 b=b||jsonb_build_object('starts_at',start_at+interval '3 hours','email','fixture-expired@example.invalid');
 r=public.begin_booking(gen_random_uuid(),repeat('a',64),b,'fixture-fingerprint',false);
 update public.appointment_holds set expires_at=now()-interval '1 minute' where id=r.hold_id;
 update public.booking_requests set expires_at=now()-interval '1 minute' where public.booking_requests.id=r.id;
 perform public.expire_checkouts();
 if not exists(select 1 from public.available_slots(service,(start_at at time zone 'America/Chicago')::date) where starts_at=start_at+interval '3 hours') then raise exception 'TEST: abandoned checkout did not release slot';end if;
 if public.apply_payment_event('evt_late','paid',r.id,'cs_fixture_late','pi_fixture_late',1501,'usd',false)<>'refund_review' then raise exception 'TEST: late payment claimed released slot';end if;
 if (select appointment_id from public.booking_requests where public.booking_requests.id=r.id) is not null then raise exception 'TEST: late payment created appointment';end if;
 -- No-consent email reminders and global opt-outs are honored at dispatch time.
 select * into strict j from public.claim_messages('email');
 perform public.finish_message(j.id,j.lease_token,'retry',null,'fixture timeout');
 update public.notification_jobs set first_attempt_at=now()-interval '24 hours',locked_until=null where id=j.id;
 perform public.claim_messages('email');
 if (select state from public.notification_jobs where public.notification_jobs.id=j.id)<>'unknown' then raise exception 'TEST: email retried beyond provider key retention';end if;
 perform public.suppress_contact(salon,'email','fixture-paid@example.invalid','customer_opt_out');
 if public.message_is_current(j.id) then raise exception 'TEST: opt-out ignored';end if;
 -- SMS lease crashes never authorize a second provider call; stale reminders expire.
 update public.booking_policies set payments_enabled=false where salon_id=salon;
 update public.communication_settings set sms_enabled=true where salon_id=salon;
 b=b||jsonb_build_object('starts_at',start_at+interval '4 hours','email','fixture-sms@example.invalid','sms_consent',true,'email_reminders_consent',true);
 r=public.begin_booking(gen_random_uuid(),repeat('a',64),b);
 select * into strict j from public.claim_messages('sms');
 update public.notification_jobs set locked_until=now()-interval '1 minute' where public.notification_jobs.id=j.id;
 -- Materialize the mutating call before reading state; SQL expressions do not guarantee evaluation order.
 select count(*) into count_before from public.claim_messages('sms');
 if count_before<>0 then raise exception 'TEST: ambiguous SMS was claimed again';end if;
 if (select state from public.notification_jobs where public.notification_jobs.id=j.id)<>'unknown' then raise exception 'TEST: ambiguous SMS not marked unknown';end if;
 update public.notification_jobs set due_at=now()-interval '31 minutes',expires_at=now()-interval '1 minute' where appointment_id=r.appointment_id and kind='reminder';
 perform public.claim_messages('email');
 if exists(select 1 from public.notification_jobs where appointment_id=r.appointment_id and kind='reminder' and state<>'suppressed') then raise exception 'TEST: overdue reminders still eligible';end if;
 perform public.suppress_contact(salon,'sms','+15550000001','provider_opt_out');
 if not exists(select 1 from public.message_suppressions where salon_id=salon and channel='sms') then raise exception 'TEST: SMS STOP not persisted';end if;
 insert into auth.users(id,email) values(gen_random_uuid(),'communications-owner@example.invalid') returning id into owner_id;
 insert into auth.users(id,email) values(gen_random_uuid(),'communications-outsider@example.invalid') returning id into outsider;
 insert into public.staff_roles(salon_id,user_id,role) values(salon,owner_id,'owner');
 perform set_config('test.comms_salon',salon::text,true);perform set_config('test.comms_owner',owner_id::text,true);perform set_config('test.comms_outsider',outsider::text,true);
end $$;
select set_config('request.jwt.claim.sub',current_setting('test.comms_outsider'),true);
set local role authenticated;
do $$ declare bad boolean=false;begin
 if exists(select 1 from public.booking_requests) or exists(select 1 from public.notification_jobs) or exists(select 1 from public.notification_events) or exists(select 1 from public.message_suppressions) then raise exception 'TEST: outsider read private communications/payment data';end if;
 begin perform public.apply_payment_event('fake','paid',gen_random_uuid(),'fake','pi_fake',100,'usd',false);exception when insufficient_privilege then bad=true;end;if not bad then raise exception 'TEST: outsider forged payment';end if;
 update public.communication_settings set reminders_enabled=true where salon_id=current_setting('test.comms_salon')::uuid;if found then raise exception 'TEST: outsider edited messaging';end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.comms_owner'),true);
set local role authenticated;
do $$ begin
 update public.communication_settings set reminders_enabled=false where salon_id=current_setting('test.comms_salon')::uuid;if not found then raise exception 'TEST: owner cannot disable reminders';end if;
 if not exists(select 1 from public.booking_requests where salon_id=current_setting('test.comms_salon')::uuid) then raise exception 'TEST: owner cannot see payment records';end if;
end $$;
reset role;
set local role anon;
do $$ declare bad boolean=false;begin
 begin perform id from public.booking_requests;exception when insufficient_privilege then bad=true;end;if not bad then raise exception 'TEST: anonymous payment records exposed';end if;
 bad=false;begin perform public.claim_messages('email');exception when insufficient_privilege then bad=true;end;if not bad then raise exception 'TEST: anonymous queue claim accepted';end if;
end $$;
reset role;
rollback;
select 'Consent, reminder approval, reschedule/cancel, leases, immutable retries, deduplication, authenticated delivery, payment confirmation, duplicate/invalid/late payments, refunds, hold expiry and private owner authorization passed.' as result;
